M="pharm-repro"
BOSS=dict(th="เคสใหญ่: ปัสสาวะกลางคืนบ่อย",en="Boss case: Up at night to urinate",
case="A 68-year-old man has weak stream, hesitancy and nocturia three times a night. Digital rectal exam: smooth, symmetrically enlarged prostate. PSA mildly elevated for age. He also has erectile dysfunction.",
qs=[
("Diagnosis:",["Benign prostatic hyperplasia","Prostate adenocarcinoma","Chronic bacterial prostatitis","Neurogenic bladder dysfunction"],0,"Smooth, symmetric enlargement of the transition zone."),
("Fastest symptom relief comes from:",["α₁ antagonist (tamsulosin)","5α-reductase inhibitor (finasteride)","Testosterone replacement","GnRH agonist (leuprolide)"],0,"Relaxes prostatic and bladder neck smooth muscle."),
("Finasteride works by:",["Inhibiting 5α-reductase → ↓ DHT","Blocking α₁ receptors in the prostate","Blocking androgen receptors","Inhibiting aromatase → ↓ estrogen"],0,"Shrinks the prostate over months and lowers PSA ~50%."),
("Tadalafil helps both BPH and ED via:",["PDE5 inhibition → ↑ cGMP","α₁ blockade → ↓ stromal tone","5α-reductase inhibition → ↓ DHT","D₂ agonism → ↓ prolactin"],0,"Do not combine with nitrates."),
("A key adverse effect of tamsulosin to warn about:",["Intraoperative floppy-iris syndrome","Hyperkalemia with muscle weakness","Gynecomastia and breast tenderness","Drug-induced hepatotoxicity"],0,"Mention before cataract surgery; also first-dose orthostatic hypotension."),
("Which drug class worsens urinary retention and should be avoided?",["Anticholinergics (e.g., oxybutynin)","α₁ blockers (e.g., tamsulosin)","PDE5 inhibitors (e.g., tadalafil)","5α-reductase inhibitors (e.g., finasteride)"],0,"First-generation antihistamines and decongestants also worsen retention."),
],pass_=4)
T={
"hpg":[("Continuous GnRH agonist exposure causes:",["↓ LH/FSH after an initial flare","Sustained ↑ LH/FSH secretion","No change in LH or FSH levels","Selective ↑ FSH with ↓ LH"],0,"Pulsatile use stimulates; continuous suppresses."),
 ("Clomiphene induces ovulation by:",["Blocking hypothalamic estrogen feedback","Acting directly as an LH analog","Stimulating ovarian aromatase","Agonizing progesterone receptors"],0,"Loss of negative feedback → ↑ GnRH, LH, FSH; used in PCOS infertility."),
 ('A 24-year-old female marathon runner has had no menses for 8 months. BMI is 17 kg/m², pregnancy test is negative, LH, FSH and estradiol are low, and prolactin and TSH are normal. Mechanism of her amenorrhea?', ['↓ Pulsatile GnRH release from hypothalamus', 'Primary ovarian failure with ↑ FSH feedback', 'Prolactin-mediated suppression of GnRH', 'Androgen excess from ovarian theca cells'], 0, 'Functional hypothalamic amenorrhea (energy deficit, exercise) suppresses GnRH pulses → low LH/FSH/estradiol; ovarian failure would give high FSH.', 3)],
"gnrh":[("Leuprolide is used continuously for:",["Prostate cancer and endometriosis","Benign prostatic hyperplasia","Postmenopausal osteoporosis","Inducing ovulation in PCOS"],0,"Also central precocious puberty; initial testosterone flare can be blocked with flutamide."),
 ("Degarelix differs from leuprolide because it:",["Is a GnRH antagonist with no flare","Is a GnRH agonist with a flare","Is a synthetic androgen","Is an aromatase inhibitor"],0,"Immediate suppression."),
 ('A 72-year-old man with metastatic prostate cancer and vertebral metastases starts leuprolide. One week later he has worsening back pain and urinary retention. Which drug given at initiation would have prevented this?', ['Flutamide (androgen receptor blocker)', 'Finasteride (5α-reductase inhibitor)', 'Tamsulosin (α₁ blocker)', 'Anastrozole (aromatase inhibitor)'], 0, 'Continuous GnRH agonist first causes an LH and testosterone flare; an androgen receptor blocker (or a GnRH antagonist instead) prevents it. Finasteride does not block testosterone action.', 3)],
"estrogen":[("Estrogen therapy risks include:",["VTE and endometrial cancer","Osteoporosis and hip fracture","Hypotension and bradycardia","Hypoglycemia and weight loss"],0,"Endometrial cancer if unopposed; add progestin if the uterus is present."),
 ("A contraindication to estrogen:",["Prior DVT or ER+ breast cancer","Menopausal hot flashes","Postmenopausal osteopenia","Treated hypothyroidism"],0,"Also smokers > 35 years."),
 ('A 53-year-old woman with an intact uterus takes estradiol alone for hot flashes. Two years later she has postmenopausal bleeding, and endometrial biopsy shows hyperplasia without atypia. What should have been added to her regimen?', ['Cyclic progestin therapy', 'Tamoxifen (SERM) therapy', 'Aromatase inhibitor therapy', 'Low-dose androgen therapy'], 0, 'Unopposed estrogen drives endometrial proliferation; a progestin protects the endometrium. Tamoxifen is itself an endometrial agonist.', 3)],
"serm":[("Raloxifene is used for:",["Osteoporosis and breast cancer prevention","Endometrial hyperplasia and cancer","Vasomotor hot flashes of menopause","Contraception and cycle control"],0,"Agonist at bone, antagonist at breast and uterus; ↑ VTE."),
 ("Letrozole works by:",["Inhibiting aromatase","Blocking estrogen receptors","Blocking progesterone receptors","Agonizing GnRH receptors"],0,"Used in ER+ postmenopausal breast cancer and ovulation induction."),
 ('A 58-year-old postmenopausal woman has taken a drug for 3 years after resection of an ER-positive breast cancer. She now has vaginal bleeding, and ultrasound shows a thickened endometrium. Her bone density has been preserved. Mechanism of this adverse effect?', ['Partial estrogen agonism at the endometrium', 'Estrogen receptor blockade at the endometrium', 'Aromatase inhibition in adipose tissue', 'Progesterone receptor agonism in the uterus'], 0, 'Tamoxifen is an antagonist at breast but an agonist at endometrium and bone → endometrial hyperplasia/cancer; aromatase inhibitors would cause bone loss, not endometrial growth.', 3)],
"progestin":[("Mifepristone is a:",["Progesterone receptor antagonist","Synthetic progestin (PR agonist)","Selective estrogen receptor modulator","GnRH receptor agonist"],0,"Combined with misoprostol for medical abortion."),
 ("Medroxyprogesterone acetate injection can cause:",["Reversible bone loss","Sustained hypertension","Severe hyperkalemia","Secondary polycythemia"],0,"Loss of bone mineral density; depot contraceptive every 3 months."),
 ("A 26-year-old woman at 7 weeks' gestation by ultrasound requests medical termination of pregnancy. She receives a standard two-drug regimen, the second being misoprostol taken 24–48 hours later. The first drug acts by:", ['Blocking progesterone receptors', 'Stimulating prostaglandin E₁ receptors', 'Blocking estrogen receptors', 'Agonizing oxytocin receptors'], 0, 'Mifepristone is a progesterone receptor antagonist that destabilizes the decidua; misoprostol (PGE₁ analog) then induces uterine contractions.', 3)],
"contra":[("Combined oral contraceptives prevent pregnancy mainly by:",["Inhibiting LH surge → no ovulation","Directly killing sperm in the vagina","Triggering a premature LH surge","Stimulating FSH-driven follicle growth"],0,"Progestin also thickens cervical mucus."),
 ("The copper IUD works by:",["Sterile inflammation toxic to sperm","Releasing levonorgestrel locally","Suppressing the midcycle LH surge","Releasing estrogen into the uterus"],0,"The local reaction is toxic to sperm and ova; non-hormonal; heavier periods."),
 ('A 37-year-old woman who smokes 20 cigarettes daily and has migraine with aura requests reliable contraception. Which method is contraindicated?', ['Combined estrogen–progestin pill', 'Levonorgestrel intrauterine device', 'Copper intrauterine device', 'Progestin-only implant'], 0, 'Estrogen raises the risk of ischemic stroke and VTE, greatest with smoking ≥ 35 years and migraine with aura; progestin-only and copper methods are acceptable.', 2)],
"androgen":[("Exogenous testosterone causes:",["Testicular atrophy and ↓ sperm count","↑ Sperm count and improved fertility","Hypotension and bradycardia","Anemia from ↓ erythropoiesis"],0,"Negative feedback on LH/FSH."),
 ("Danazol was used for endometriosis and can cause:",["Acne, hirsutism and weight gain","Hyperkalemia and acidosis","Hypotension and syncope","Hypoglycemia and weight loss"],0,"Synthetic androgen, partial agonist; androgenic effects."),
 ('A 26-year-old competitive bodybuilder has acne, gynecomastia and small, soft testes. Hematocrit is 54%, LH and FSH are suppressed, and semen analysis shows azoospermia. Most likely cause?', ['Exogenous anabolic steroid use', 'Klinefelter syndrome (47,XXY)', 'Primary testicular failure', 'Prolactin-secreting adenoma'], 0, 'Exogenous androgens suppress LH/FSH → testicular atrophy and azoospermia, raise hematocrit, and aromatize to estrogen (gynecomastia). Klinefelter and primary failure have high LH/FSH.', 2)],
"antiandrogen":[("Spironolactone is used in PCOS hirsutism because it:",["Blocks androgen receptors","Inhibits ovarian aromatase","Agonizes GnRH receptors","Is a GnRH antagonist"],0,"Also ↓ androgen synthesis; causes gynecomastia in men."),
 ("Flutamide is a:",["Androgen receptor antagonist","Type II 5α-reductase inhibitor","GnRH agonist","Aromatase inhibitor"],0,"Used with GnRH agonists in prostate cancer."),
 ('A 63-year-old man with heart failure with reduced ejection fraction has taken spironolactone for a year and now has painful bilateral breast enlargement. Mechanism of this adverse effect?', ['Androgen receptor antagonism', 'Aldosterone receptor agonism', '5α-reductase type 2 induction', 'Dopamine D₂ receptor blockade'], 0, 'Spironolactone blocks androgen receptors (and ↓ testosterone synthesis), causing gynecomastia; eplerenone is more selective and avoids it.', 2)],
"labor":[("Oxytocin is used to:",["Induce labor and control postpartum hemorrhage","Stop preterm labor and delay delivery","Prevent eclamptic seizures in preeclampsia","Suppress lactation after delivery"],0,"Water intoxication at high doses."),
 ("Tocolytics include:",["Nifedipine, indomethacin, terbutaline","Oxytocin, misoprostol, dinoprostone","Methylergonovine, carboprost, oxytocin","Mifepristone, misoprostol, carboprost"],0,"Delay preterm labor to give steroids."),
 ('A 30-year-old woman delivers vaginally after a prolonged labor. Twenty minutes later she has heavy vaginal bleeding; the uterus is soft and boggy above the umbilicus, and the placenta was delivered intact. Most appropriate first drug?', ['Oxytocin', 'Terbutaline', 'Nifedipine', 'Magnesium sulfate'], 0, 'Uterine atony is the commonest cause of postpartum hemorrhage; oxytocin contracts the myometrium. Terbutaline and nifedipine are tocolytics and would relax the uterus.', 2)],
"uro":[("PDE5 inhibitors are contraindicated with:",["Nitrates","Statins","Metformin","ACE inhibitors"],0,"Profound hypotension."),
 ("Sildenafil can cause:",["Blue-tinted vision","Yellow vision","Night blindness","Diplopia"],0,"PDE6 cross-reactivity in the retina."),
 ('A 60-year-old man with stable angina takes isosorbide mononitrate daily and asks for a drug for erectile dysfunction. Sildenafil is withheld because both drugs:', ['↑ cGMP in vascular smooth muscle', '↑ cAMP in vascular smooth muscle', 'Block L-type Ca²⁺ channels', 'Block α₁-adrenergic receptors'], 0, 'Nitrates stimulate guanylyl cyclase (via NO) and PDE5 inhibitors prevent cGMP breakdown; together they cause profound hypotension. Neither acts through cAMP.', 3)],
}
